import json, sys
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/dev')
import gen2
import instance as I
x = gen2.gen_instance(6)
print('snapshots:')
for s in x['snapshots']:
    print(' bounds', s['bounds'], 'ctrl', s['controller'], 'tol', s['tolerance'])
    for o in s['observations']:
        print('   ', o)
# check name validity of every target
nodes = set(x['nodes']); edges = set(e['id'] for e in x['edges']); comms = set(c['id'] for c in x['commodities']); doms = set(x['domains'])
for s in x['snapshots']:
    for o in s['observations']:
        if o['metric'] == 'demand' and o['target'] not in comms: print('BAD demand target', o)
        if o['metric'] == 'link' and o['target'] not in edges: print('BAD link target', o)
        if o['metric'] in ('ingress','egress') and o['target'] not in nodes: print('BAD node target', o)
        if o['domain'] is not None and o['domain'] not in doms: print('BAD domain', o)
        if not I.is_name(o['id']): print('BAD obs id', o['id'])
print('total obs', sum(len(s['observations']) for s in x['snapshots']))
EOF
